def ref(env, episodes=500, alpha=.5, gamma=.9, epsilon=.1, n_steps=5, seed=0, max_steps=1000):
    actions=("U","R","D","L")
    reach=set(); st=env.reset(); reach.add(st)
    stack=[st]
    while stack:
        r,c=stack.pop()
        for dr,dc in ((-1,0),(0,1),(1,0),(0,-1)):
            n=(r+dr,c+dc)
            if n not in reach and env._in_bounds(n) and env._cell(n)!="#":
                reach.add(n); stack.append(n)
    Q={(s,a):0.0 for s in sorted(reach) if env._cell(s)!="G" for a in actions}
    rng=random.Random(seed)
    def pick(s):
        if rng.random()<epsilon:
            return actions[rng.randrange(4)]
        return max(actions, key=lambda a: Q[(s,a)])
    def pi(s):
        g=max(actions,key=lambda a:Q[(s,a)])
        return {a:(1-epsilon+epsilon/4 if a==g else epsilon/4) for a in actions}
    for _ in range(episodes):
